using System.Diagnostics;
using System.Text.Json;
namespace AgenticUrlShortener;
// Explicit DAG: independent design/security nodes run concurrently, followed by a join.
public class WorkflowEngine(JsonStore<WorkflowCollection> store,ILogger<WorkflowEngine> logger){
 public static readonly Dictionary<string,string[]> Graph=new(){["requirements"]=[],["planning"]=["requirements"],["design"]=["planning"],["security"]=["planning"],["implementation"]=["design","security"],["tests"]=["implementation"],["documentation"]=["implementation"],["review"]=["tests","documentation"],["approval"]=["review"],["release"]=["approval"]};
 private readonly System.Collections.Concurrent.ConcurrentDictionary<string,SemaphoreSlim> _locks=new();
 private static void Log(WorkflowState w,string kind,string detail){lock(w){w.Audit.Add(new AuditEvent(DateTime.UtcNow,kind,detail));}}
 public async Task<WorkflowState> Create(WorkflowRequest req){if(string.IsNullOrWhiteSpace(req.Requirement)||req.Requirement.Length>4000)throw new ArgumentException("Requirement must be 1-4000 characters");if(!new[]{"greenfield","brownfield","ambiguous"}.Contains(req.Scenario.ToLowerInvariant()))throw new ArgumentException("Scenario must be greenfield, brownfield or ambiguous");var w=new WorkflowState{Requirement=req.Requirement,Scenario=req.Scenario.ToLowerInvariant(),SimulateTestFailure=req.SimulateTestFailure,Nodes=Graph.ToDictionary(x=>x.Key,x=>new NodeState{Id=x.Key,Dependencies=x.Value})};Log(w,"created","Requirement accepted; policy: no auto-deployment or unapproved release");await Save(w);return await Advance(w.Id);}
 private Task Save(WorkflowState w)=>store.Update(data=>{data.Items[w.Id]=w;return true;});
 public Task<WorkflowState?> Get(string id)=>store.Read(data=>data.Items.GetValueOrDefault(id));
 public Task<List<WorkflowState>> All()=>store.Read(data=>data.Items.Values.OrderByDescending(w=>w.StartedUtc).ToList());
 public async Task<WorkflowState> Advance(string id){var gate=_locks.GetOrAdd(id,_=>new SemaphoreSlim(1,1));await gate.WaitAsync();try{var w=await Get(id)??throw new KeyNotFoundException("Workflow not found");if(w.Status is "Rejected" or "Completed" or "SafeStopped")return w;
 while(true){var ready=w.Nodes.Values.Where(n=>n.Status==NodeStatus.Pending && n.Dependencies.All(d=>w.Nodes[d].Status==NodeStatus.Completed)).ToList();if(ready.Count==0)break;
 // Join/synchronization is represented by the dependency checks above.
 await Task.WhenAll(ready.Select(n=>Execute(w,n)));
 await Save(w);
 if(w.Status=="SafeStopped")break;
 }
 if(w.Nodes["approval"].Status==NodeStatus.WaitingApproval)w.Status="WaitingApproval";
 else if(w.Nodes.Values.All(n=>n.Status==NodeStatus.Completed)){w.Status="Completed";w.EndedUtc=DateTime.UtcNow;Log(w,"complete","All exit gates satisfied; release readiness approved (no production deployment)");}
 await Save(w);return w;
 }finally{gate.Release();}}
 private async Task Execute(WorkflowState w,NodeState n){n.Status=NodeStatus.Running;Log(w,"start",n.Id);for(int attempt=1;attempt<=3;attempt++){n.Attempts++;try{var output=await AgentOutput(w,n.Id);lock(w){n.Output=output;w.Artifacts[n.Id]=output;n.Status=n.Id=="approval"?NodeStatus.WaitingApproval:NodeStatus.Completed;}Log(w,n.Status==NodeStatus.WaitingApproval?"approval_required":"success",n.Id+" attempt="+attempt);return;}catch(Exception ex){n.Error=ex.Message;Log(w,"error",n.Id+" attempt="+attempt+": "+ex.Message);if(attempt<3){w.Retries++;Log(w,"retry",n.Id+" bounded retry");await Task.Delay(20*attempt);}else{n.Status=NodeStatus.Failed;w.Status="SafeStopped";w.EndedUtc=DateTime.UtcNow;Log(w,"safe_stop",n.Id+" exhausted retry budget");logger.LogWarning(ex,"Workflow {Id} safely stopped",w.Id);}}}}
 private static Task<string> AgentOutput(WorkflowState w,string node){string result=node switch{
 "requirements"=>JsonSerializer.Serialize(new{intent=w.Requirement,scenario=w.Scenario,assumptions=w.Scenario=="ambiguous"?new[]{"Clarification needed: define what secure means; assume HTTP(S) validation and approval for now"}:new[]{"Service accepts HTTP(S) URLs"},acceptanceCriteria=new[]{"URL can be shortened","Redirect is tracked","Failures are observable"}}),
 "planning"=>"Dependency DAG: requirements -> planning -> (design || security) -> implementation -> (tests || documentation) -> review -> approval -> release. Human gate required.",
 "design"=>"ASP.NET Core minimal APIs, JSON persistence with atomic replace, crypto-random codes; trade-off: single-instance persistence, not distributed.",
 "security"=>"Policy checks: HTTP(S) only, no credentials in target URL, bounded input, cryptographic short codes, approval required for release. Remaining risk: redirect abuse and private-network targets.",
 "implementation"=>"Verified repository implementation scope: create/resolve/analytics/disable endpoints in UrlService; code modifications require human review before release.",
 "tests"=>w.SimulateTestFailure&&!w.FailureConsumed?ThrowSimulated(w):"Validation plan: URL scheme rejection, unique codes, expired/disabled redirects, analytics counts, approval gate, retries and replan. See xUnit suite and manual curl examples.",
 "documentation"=>"README, architecture, threat model, scenarios and limitations. Reviewer can reproduce with dotnet run and dotnet test.",
 "review"=>"Review evidence: design, security, implementation, tests and documentation joined; approval required before release readiness.",
 "approval"=>"Awaiting named human approval. POST /api/workflows/{id}/approval with approved=true or false.",
 "release"=>"Release readiness approved by "+w.ApprovedBy+"; no automatic external deployment is performed.",
 _=>throw new InvalidOperationException("Unknown agent")};return Task.FromResult(result);}
 private static string ThrowSimulated(WorkflowState w){w.FailureConsumed=true;throw new InvalidOperationException("Injected transient test runner failure");}
 public async Task<WorkflowState> Approve(string id,ApprovalRequest req){var gate=_locks.GetOrAdd(id,_=>new SemaphoreSlim(1,1));await gate.WaitAsync();try{var w=await Get(id)??throw new KeyNotFoundException("Workflow not found");if(w.Status!="WaitingApproval")throw new InvalidOperationException("Workflow is not awaiting approval");if(string.IsNullOrWhiteSpace(req.Reviewer))throw new ArgumentException("Reviewer required");var n=w.Nodes["approval"];if(req.Approved){w.ApprovedBy=req.Reviewer;n.Status=NodeStatus.Completed;Log(w,"approved",req.Reviewer+": "+(req.Reason??"approved"));w.Status="Running";}else{n.Status=NodeStatus.Failed;w.Status="Rejected";w.EndedUtc=DateTime.UtcNow;w.RejectionReason=req.Reason;w.Rollbacks++;w.Artifacts.Remove("release");Log(w,"rollback","Approval rejected by "+req.Reviewer+"; pending release cancelled");}await Save(w);}finally{gate.Release();}return await Advance(id);}
 public async Task<WorkflowState> Replan(string id,string newRequirement){if(string.IsNullOrWhiteSpace(newRequirement))throw new ArgumentException("Requirement required");var gate=_locks.GetOrAdd(id,_=>new SemaphoreSlim(1,1));await gate.WaitAsync();try{var w=await Get(id)??throw new KeyNotFoundException("Workflow not found");if(w.Status=="Completed")throw new InvalidOperationException("Completed workflow is immutable; create a new one");w.Revision++;w.Requirement=newRequirement;w.Status="Running";w.ApprovedBy=null;w.EndedUtc=null;foreach(var n in w.Nodes.Values){n.Status=NodeStatus.Pending;n.Output=null;n.Error=null;n.Attempts=0;}w.Artifacts.Clear();w.Rollbacks++;Log(w,"replan","Upstream requirement changed; downstream outputs invalidated; revision "+w.Revision);await Save(w);}finally{gate.Release();}return await Advance(id);}
 public async Task<object> Metrics(){var all=await All();var done=all.Where(w=>w.EndedUtc!=null).ToList();return new {Total=all.Count,Completed=all.Count(w=>w.Status=="Completed"),SuccessRate=done.Count==0?0:(double)done.Count(w=>w.Status=="Completed")/done.Count,RetryFrequency=all.Sum(w=>w.Retries),RollbackFrequency=all.Sum(w=>w.Rollbacks),MeanTimeToRecoveryMs=all.Where(w=>w.Retries>0&&w.EndedUtc!=null).Select(w=>(w.EndedUtc!.Value-w.StartedUtc).TotalMilliseconds).DefaultIfEmpty(0).Average(),MeanEndToEndLatencyMs=done.Select(w=>(w.EndedUtc!.Value-w.StartedUtc).TotalMilliseconds).DefaultIfEmpty(0).Average(),Note="MTTR proxy: workflow duration for completed/rejected/safe-stopped runs with retries; not incident-level MTTR"};}
}
